/// # Safety
/// Both pointers must be valid, aligned reads.
unsafe fn read_both(p: *const i32, q: *const i32) -> i32 {
    *p + *q
}

fn main() {
    let (a, b) = (40, 2);
    let total = unsafe { read_both(&a, &b) };
    println!("{total}");
}

